// Convex signs `${timestamp}.${rawBody}` with HMAC-SHA256.
// Check it against the exact bytes we received, not a re-serialised copy.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'] || '';
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

let valid = false;
if (secret && ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(sig);
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
}

return [{ json: { valid, payload: valid ? JSON.parse(raw) : null } }];

// Convex retries if it doesn't get a 2xx. If our reply got lost after we
// already notified, the retry carries the same key and we don't send twice.
const seen = $getWorkflowStaticData('global');
seen.keys = seen.keys || {};
const weekAgo = Date.now() - 7 * 86400000;
for (const [k, t] of Object.entries(seen.keys)) if (t < weekAgo) delete seen.keys[k];

const p = $input.first().json.payload;
const duplicate = Boolean(seen.keys[p.key]);
if (!duplicate) seen.keys[p.key] = Date.now();
return [{ json: { ...p, duplicate } }];

// Swap this node for Send Email / Slack in a real setup. It only gets the
// recipient's first name and email plus the loan facts it has to mention.
const p = $input.first().json;
if (p.duplicate) return [{ json: { delivered: false, reason: 'duplicate', key: p.key } }];

const lines = {
  requested: `${p.recipient.firstName}, someone asked to borrow your ${p.toolName} (${p.startDate} to ${p.endDate}).`,
  approved: `${p.recipient.firstName}, your request for the ${p.toolName} was approved. Pick-up from ${p.startDate}.`,
  declined: `${p.recipient.firstName}, your request for the ${p.toolName} was declined.`,
  cancelled: `${p.recipient.firstName}, a request for your ${p.toolName} was cancelled.`,
  returned: `${p.recipient.firstName}, thanks for returning the ${p.toolName}.`,
};
const message = lines[p.status] || `${p.recipient.firstName}, a loan for the ${p.toolName} changed to ${p.status}.`;
console.log(`[lendloop] notify ${p.recipient.email}: ${message}`);
return [{ json: { delivered: true, to: p.recipient.email, message, key: p.key } }];
